Decomposition forecasting


Code
retail_components &lt;- aus_retail |&gt;
  summarise(Turnover = sum(Turnover)) |&gt; 
  model(STL(box_cox(Turnover, lambda = 0.2) ~ season(window = Inf))) |&gt; 
  components() |&gt; 
  transmute(`box_cox(Turnover, lambda = 0.2)`, `Seasonally Adjusted (T + R)` = season_adjust, `Seasonality (S)` = season_year) |&gt; 
  pivot_longer(c(`box_cox(Turnover, lambda = 0.2)`, `Seasonally Adjusted (T + R)`, `Seasonality (S)`), names_to = "component")

retail_components |&gt; 
  ggplot(aes(x = Month, y = value)) +
  geom_line() +
  facet_wrap(vars(component), ncol = 1, scales = "free_y")

Decomposition forecasting


Code
retail_fc_snaive &lt;- retail_components |&gt; 
  filter(component == "Seasonality (S)") |&gt; 
  model(SNAIVE(value)) |&gt; 
  forecast(h = "2 years") |&gt; 
  mutate(component = "Seasonality (S)")

retail_components |&gt; 
  filter(Month &gt; yearmonth("2010 Jan")) |&gt;
  ggplot(aes(x = Month, y = value)) +
  geom_line() +
  autolayer(retail_fc_snaive) +
  facet_wrap(vars(component), ncol = 1, scales = "free_y")

Decomposition forecasting


Code
retail_fc_ets &lt;- retail_components |&gt; 
  filter(component == "Seasonally Adjusted (T + R)") |&gt; 
  model(ETS(value)) |&gt; 
  forecast(h = "2 years") |&gt; 
  mutate(component = "Seasonally Adjusted (T + R)")

retail_components |&gt; 
  filter(Month &gt; yearmonth("2010 Jan")) |&gt;
  ggplot(aes(x = Month, y = value)) +
  geom_line() +
  autolayer(retail_fc_snaive) +
  autolayer(retail_fc_ets) +
  facet_wrap(vars(component), ncol = 1, scales = "free_y")

Decomposition forecasting


Code
retail_fc_dcmp &lt;- retail_components |&gt; 
  filter(component == "box_cox(Turnover, lambda = 0.2)") |&gt; 
  model(    
    decomposition_model(
      dcmp = STL(value ~ season(window = Inf)),
      ETS(season_adjust),
      SNAIVE(season_year)
    )
  ) |&gt; 
  forecast(h = "2 years") |&gt; 
  mutate(component = "box_cox(Turnover, lambda = 0.2)")

retail_components |&gt; 
  filter(Month &gt; yearmonth("2010 Jan")) |&gt;
  ggplot(aes(x = Month, y = value)) +
  geom_line() +
  autolayer(retail_fc_snaive) +
  autolayer(retail_fc_ets) +
  autolayer(retail_fc_dcmp) +
  facet_wrap(vars(component), ncol = 1, scales = "free_y")

